  "recommendation": "EcoCard",
  "reason": "It has the strongest currently published promotional sign-up offer I found: 2,000 sustainability points, redeemable at $0.01 each for a $20 statement credit or checking-account deposit.",
  "offer_details": {
    "required_spend": "$5,000 in eligible purchases within the first month",
